  double ex=p[5*k+3],ey=p[5*k+4],d=(.905644482*p[5*k+2]+1.6516933/px)*scale;
  double hw=w*.5;
  double xmin=std::min(x,x-d*ex)-hw*std::abs(ey)-1,xmax=std::max(x,x-d*ex)+hw*std::abs(ey)+1;
  double ymin=std::min(y,y-d*ey)-hw*std::abs(ex)-1,ymax=std::max(y,y-d*ey)+hw*std::abs(ex)+1;
